def check_graph():
    edges = []
    for i in range(5):
        for j in range(5, 11):
            edges.append((i, j))

    degrees = [0] * 11
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1

    print("Edges:", edges)
    print("Degrees:", degrees)
    print("Min degree:", min(degrees))

check_graph()

